customChrome.navSnippet:
function MyNav({ page, go }) {
  const inDrawer = useAppShell()?.navPlacement === "drawer";
  return (
    <SideNavRoot aria-label="Acme" radius={inDrawer ? "md" : "none"} open>
      <SideNavNav>
        <SideNavSection label="Work">
          <SideNavItem label="Home" icon="House" active={page === "home"} onClick={() => go("home")} />
        </SideNavSection>
      </SideNavNav>
    </SideNavRoot>
  );
}
